def _parse_money(value: str) -> Decimal:
    """The dollar amount on a line, ignoring numbers in trailing notes."""
    # The amount comes right after the dollars sign when one is present
    # ("Stop Off: $100.00 (1 extra stop)"), so trailing counts in a note
    # ("after 2 hrs free") can't be mistaken for the amount.
    match = _MONEY.search(value) or _NUMBER.search(value)
    if not match:
        raise RateConError(f"no amount in {value!r}")
    return Decimal(match.group(1) if match.re is _MONEY else match.group(0)).replace(",", "")

def _bridge_spans(axle_count: int, tandems: set[int]) -> list[tuple[int, int]]:
    """The groups the bridge formula is checked on: every run of two or more axles.

    A group that is just one tandem is covered by the tandem limit instead.
    """
    return [
        (first, last)
        for first in range(axle_count)
        for last in range(first + 1, axle_count)
        if not (last - first == 1 and first in tandems)
    ]

